'use strict';

/**
 * Embeds hash-wasm's UMD bundle as a TS string so the invisible WebView can
 * run the SAME Argon2id implementation as the desktop app (WKWebView has
 * WebAssembly; Hermes does not — pure-JS derivation takes minutes there).
 *
 * Run after bumping the hash-wasm version:  node scripts/embed-hash-wasm.cjs
 * The generated file is committed so builds don't depend on this script.
 */

const fs = require('node:fs');
const path = require('node:path');

const source = require.resolve('hash-wasm/dist/index.umd.min.js');
const code = fs.readFileSync(source, 'utf8');
const version = require(require.resolve('hash-wasm/package.json')).version;

const out = `// AUTO-GENERATED by scripts/embed-hash-wasm.cjs — do not edit (eslint-ignored).
// hash-wasm@${version} UMD bundle (global \`hashwasm\`), executed inside the
// Argon2 WebView (see src/components/Argon2WebView.tsx).
export const HASH_WASM_UMD: string = ${JSON.stringify(code)};
`;

const target = path.join(__dirname, '..', 'src', 'lib', 'hash-wasm-umd.ts');
fs.writeFileSync(target, out);
console.log(`embedded hash-wasm@${version} (${(code.length / 1024).toFixed(0)} KiB) -> ${target}`);
